import pytest
from rest_framework.test import APIClient

pytestmark = pytest.mark.django_db


@pytest.fixture
def client():
    return APIClient()


def test_a_new_workgroup_has_no_projects(client):
    response = client.get("/api/projects/", {"workgroup": "wg-empty"})
    assert response.status_code == 200
    assert response.json() == []


def test_create_a_project(client):
    response = client.post("/api/projects/", {"name": "Lung CT", "workgroup": "wg-rhino"}, format="json")
    assert response.status_code == 201
    assert response.json()["name"] == "Lung CT"


def test_a_project_needs_a_name(client):
    response = client.post("/api/projects/", {"name": "", "workgroup": "wg-rhino"}, format="json")
    assert response.status_code == 400
    assert response.json() == {"name": ["This field may not be blank."]}

